"""The retrieval seam: a backend-agnostic + its DTOs.

Every retrieval backend (local in-process, InKeep, future ones) subclasses
``BaseRetriever`` and implements ``retrieve``, returning a ``RetrievalResponse``.
The contract is **fallible**: implementations never raise to the caller —
failures and empty results are reported via ``RetrievalStatus`` so callers
branch on data, not exceptions.

The DTOs are plain pydantic models, so they serialize cleanly over a wire
if a remote backend is ever added.
"""

from abc import ABC, abstractmethod
from enum import Enum
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field


class RetrievalStatus(str, Enum):
    """Outcome of a retrieval call."""

    OK = "ok"
    EMPTY = "empty"
    ERROR = "error"


class RetrievalResult(BaseModel):
    """A single retrieved passage with provenance."""

    content: str
    title: Optional[str] = None
    url: Optional[str] = None
    score: Optional[float] = Field(
        default=None, description="Backend-specific relevance/distance score."
    )
    source_id: Optional[str] = Field(
        default=None, description="Stable id of the source document this came from."
    )
    metadata: Dict[str, Any] = Field(default_factory=dict)


class RetrievalResponse(BaseModel):
    """The result of a retrieval call: ranked results plus an outcome status."""

    results: List[RetrievalResult] = Field(default_factory=list)
    status: RetrievalStatus = RetrievalStatus.OK
    error: Optional[str] = Field(
        default=None, description="Failure detail when status is ERROR."
    )

    @classmethod
    def of(cls, results: List[RetrievalResult]) -> "RetrievalResponse":
        """Wrap results, deriving OK/EMPTY status from whether any were found."""
        status = RetrievalStatus.OK if results else RetrievalStatus.EMPTY
        return cls(results=results, status=status)

    @classmethod
    def failed(cls, error: str) -> "RetrievalResponse":
        """Build an ERROR response carrying the failure detail (no results)."""
        return cls(results=[], status=RetrievalStatus.ERROR, error=error)


class BaseRetriever(ABC):
    """Backend-agnostic retrieval contract.

    Implementations must not raise: on failure return
    ``RetrievalResponse.failed(...)``; on no matches, an EMPTY response.
    """

    @abstractmethod
    async def retrieve(
        self,
        query: str,
        *,
        top_k: Optional[int] = None,
        filters: Optional[Dict[str, Any]] = None,
    ) -> RetrievalResponse:
        """Retrieve passages relevant to ``query``.

        Args:
            query: The user query text.
            top_k: Max results to return; falls back to the backend's default.
            filters: Optional structured metadata filters (e.g. ``{"topic": ...}``).
        """
        ...
